  insert into public.practice_topics (course_id, kind, unit, code, title, title_uz, sort_order, content)
  select c.id, 'grammar', 14, $q$KG14$q$, $q$14. Past Continuous Tense$q$, $q$O‘tgan davomli zamon · 200 ta test$q$, 14, $q${"intro":{"what":"Past Continuous — o‘tmishda ma’lum bir paytda davom etayotgan ish: At 8 o’clock yesterday I was having dinner.","when":[],"structures":[],"rules":[],"signal_words":[],"topics":[{"name":"Past Continuous: form","name_uz":"Tuzilishi","summary":"was / were + fe’l-ing. I / he / she / it → was; you / we / they → were.","usage":[{"text":"O‘tmishdagi aniq bir paytda davom etayotgan ish.","example":{"en":"At 7 pm I was doing my homework.","uz":"Kechqurun soat 7 da uy vazifamni qilayotgan edim."}},{"text":"Bir paytda davom etgan ikki ish (while).","example":{"en":"Mum was cooking while Dad was reading.","uz":"Onam ovqat pishirayotgan edi, dadam esa o‘qiyotgan edi."}}],"structure":[{"type":"+","formula":"I / he / she / it + was + verb-ing","example":{"en":"She was sleeping.","uz":"U uxlayotgan edi."}},{"type":"+","formula":"you / we / they + were + verb-ing","example":{"en":"They were playing.","uz":"Ular o‘ynayotgan edi."}},{"type":"-","formula":"wasn’t / weren’t + verb-ing","example":{"en":"I wasn’t watching TV.","uz":"Men televizor ko‘rayotgan emasdim."}},{"type":"?","formula":"Was / Were + subject + verb-ing?","example":{"en":"Were you listening?","uz":"Tinglayotgan edingmi?"}}],"signals":[{"en":"at 8 o’clock yesterday","uz":"kecha soat 8 da"},{"en":"at this time yesterday","uz":"kecha shu paytda"},{"en":"all evening","uz":"butun kechqurun"},{"en":"while","uz":"…ayotganda"}],"tip":"“I were”, “they was” — XATO. I was, they were."},{"name":"Past Continuous + Past Simple","name_uz":"when va while","summary":"Uzoq davom etgan ish (fon) — Past Continuous; uni bo‘lgan qisqa voqea — Past Simple. when + qisqa voqea; while + davomli ish.","usage":[{"text":"Davomli ish + to‘satdan voqea.","example":{"en":"I was reading when the phone rang.","uz":"Telefon jiringlaganda men o‘qiyotgan edim."}},{"text":"while + davomli ish.","example":{"en":"While we were walking, it started to rain.","uz":"Biz sayr qilayotganimizda yomg‘ir yog‘a boshladi."}}],"structure":[{"type":"+","formula":"Past Continuous + when + Past Simple","example":{"en":"She was cooking when I came.","uz":"Men kelganimda u ovqat pishirayotgan edi."}},{"type":"+","formula":"While + Past Continuous, Past Simple","example":{"en":"While I was sleeping, the cat ate my fish.","uz":"Men uxlayotganimda mushuk baliqni yeb qo‘ydi."}}],"signals":[],"tip":"Qisqa voqea (rang, came, saw) — doim Past Simple’da."}],"mistakes":[{"wrong":"I were watching TV.","right":"I was watching TV.","why":"I → was."},{"wrong":"They was playing.","right":"They were playing.","why":"they → were."},{"wrong":"I was read a book.","right":"I was reading a book.","why":"was + -ing."},{"wrong":"Did you sleeping?","right":"Were you sleeping?","why":"So‘roq — Was / Were."},{"wrong":"I was cooking while the phone rang.","right":"I was cooking when the phone rang.","why":"Qisqa voqea → when."}]},"parts":[],"translations":[],"test":[{"type":"mc","q":"Malika ___ swimming in the river at this time yesterday.","options":["is","were","was","did"],"part":0},{"type":"mc","q":"She ___ going to the park at noon yesterday.","options":["is","did","was","were"],"part":0},{"type":"mc","q":"I ___ dancing at the party at this time yesterday.","options":["am","were","was","did"],"part":0},{"type":"mc","q":"You ___ cooking dinner all evening yesterday.","options":["was","did","are","were"],"part":0},{"type":"mc","q":"He ___ going to the park at noon yesterday.","options":["were","was","is","did"],"part":0},{"type":"mc","q":"Ali ___ sleeping in the garden all evening yesterday.","options":["were","did","is","was"],"part":0},{"type":"mc","q":"My sister and I ___ sleeping in the garden at this time yesterday.","options":["did","are","was","were"],"part":0},{"type":"mc","q":"Ali ___ riding a bike at noon yesterday.","options":["was","is","did","were"],"part":0},{"type":"mc","q":"You ___ teaching maths all e