  select c.id, 'grammar', 15, $q$KG15$q$, $q$15. There is / There are / There was / There were. Some, any, no$q$, $q$Bor / bor edi, some, any, no · 200 ta test$q$, 15, $q${"intro":{"what":"There is / There are — biror joyda nimadir “bor” deyish uchun. O‘tgan zamonda — There was / There were. some, any, no — miqdor.","when":[],"structures":[],"rules":[],"signal_words":[],"topics":[{"name":"There is / There are","name_uz":"…da … bor","summary":"Birlik va sanalmaydigan ot → There is. Ko‘plik → There are. O‘tgan zamonda: was / were.","usage":[{"text":"Birlik.","example":{"en":"There is a cat on the sofa.","uz":"Divanda mushuk bor."}},{"text":"Ko‘plik.","example":{"en":"There are three books in my bag.","uz":"Sumkamda uchta kitob bor."}},{"text":"O‘tgan zamon.","example":{"en":"There were a lot of people at the party.","uz":"Bazmda ko‘p odam bor edi."}}],"structure":[{"type":"+","formula":"There is / was + singular / uncountable","example":{"en":"There is some milk.","uz":"Ozgina sut bor."}},{"type":"+","formula":"There are / were + plural","example":{"en":"There were two dogs.","uz":"Ikkita it bor edi."}},{"type":"-","formula":"There isn’t / aren’t …","example":{"en":"There aren’t any chairs.","uz":"Stul yo‘q."}},{"type":"?","formula":"Is there …? / Are there …?","example":{"en":"Is there a bank near here?","uz":"Yaqinda bank bormi?"}},{"type":"short","formula":"Yes, there is. / No, there aren’t.","example":{"en":"Are there any eggs? — No, there aren’t.","uz":"Tuxum bormi? — Yo‘q."}}],"signals":[],"tip":"There is two cats — XATO. Ko‘plik → There are two cats."},{"name":"some, any, no","name_uz":"Biroz, hech, yo‘q","summary":"some — darak gapda; any — inkor va so‘roqda; no = not any (fe’l inkor bo‘lmaydi).","usage":[{"text":"some — darak gap, iltimos va taklif.","example":{"en":"Would you like some tea?","uz":"Choy ichasizmi?"}},{"text":"any — inkor va so‘roq.","example":{"en":"Have you got any brothers?","uz":"Aka-ukang bormi?"}},{"text":"no — “yo‘q” (fe’l darak shaklida qoladi).","example":{"en":"There is no milk.","uz":"Sut yo‘q."}}],"structure":[{"type":"-","formula":"There aren’t any … = There are no …","example":{"en":"There are no shops here.","uz":"Bu yerda do‘kon yo‘q."}}],"signals":[],"tip":"“There aren’t no” — XATO (ikki inkor). aren’t any yoki are no."}],"mistakes":[{"wrong":"There is many people.","right":"There are many people.","why":"Ko‘plik → are."},{"wrong":"There was a lot of cars.","right":"There were a lot of cars.","why":"cars — ko‘plik."},{"wrong":"There aren’t some apples.","right":"There aren’t any apples.","why":"Inkor → any."},{"wrong":"There isn’t no water.","right":"There isn’t any water. / There is no water.","why":"Ikki inkor bo‘lmaydi."},{"wrong":"Is there any apples?","right":"Are there any apples?","why":"Ko‘plik → Are there."}]},"parts":[],"translations":[],"test":[{"type":"mc","q":"There ___ a computer in the room.","options":["be","is","am","are"],"part":0},{"type":"mc","q":"There ___ three windows in the kitchen.","options":["am","be","is","are"],"part":0},{"type":"mc","q":"There ___ some butter in the kitchen.","options":["is","be","are","am"],"part":0},{"type":"mc","q":"There ___ some water in the kitchen.","options":["am","are","be","is"],"part":0},{"type":"mc","q":"There ___ a lamp in the kitchen.","options":["am","be","are","is"],"part":0},{"type":"mc","q":"There ___ two eggs near the school.","options":["am","is","are","be"],"part":0},{"type":"mc","q":"There ___ a lot of cars on the table.","options":["be","are","am","is"],"part":0},{"type":"mc","q":"There ___ a pen in the garden.","options":["am","are","is","be"],"part":0},{"type":"mc","q":"There ___ some money on the table.","options":["are","be","am","is"],"part":0},{"type":"mc","q":"There ___ a lot of flowers in the kitchen.","options":["are","be","is","am"],"part":0},{"type":"mc","q":"There ___ some cheese on the table.","options":["are","be","am","is"],"part":0},{"type":"mc","q":"There ___ a dog in our street.","options":["am","is",